<script setup>
import { computed, ref, watch } from 'vue';
import RoleBadge from './RoleBadge.vue';
const props=defineProps({users:{type:Array,default:()=>[]},organizations:{type:Array,default:()=>[]},factories:{type:Array,default:()=>[]},roles:{type:Array,default:()=>[]},context:{type:Object,default:()=>({})},loading:Boolean});
const emit=defineEmits(['edit','create','refresh','reset','toggle']);
const scope=ref('all'),keyword=ref(''),status=ref('all');
const org=id=>props.organizations.find(o=>String(o.id)===String(id));
function ancestry(id){const ids=new Set();let node=org(id);while(node&&!ids.has(String(node.id))){ids.add(String(node.id));node=org(node.parent_id);}return ids;}
const home=user=>user.home_factory_id?`factory:${user.home_factory_id}`:user.organization_id?'headquarters':'unassigned';
const groups=computed(()=>[
...(props.context.scope_kind==='headquarters'?[{id:'headquarters',name:'总部',type:'总部',organization:props.organizations.find(o=>o.type==='company')?.id}]:[]),
...props.factories.map(f=>({id:`factory:${f.id}`,name:f.name,type:'厂区',organization:props.organizations.find(o=>o.type==='factory'&&String(o.factory_id)===String(f.id))?.id})),
...(props.context.scope_kind==='headquarters'?[{id:'unassigned',name:'待分配组织',type:'历史账号',organization:''}]:[])
].map(group=>({...group,users:props.users.filter(u=>home(u)===group.id)})));
const selected=computed(()=>groups.value.find(g=>g.id===scope.value));
const selectedOrg=computed(()=>scope.value.startsWith('org:')?org(scope.value.slice(4)):null);
function departmentRows(group){const root=group.organization;if(!root)return[];const rows=[];const visit=(id,depth)=>{props.organizations.filter(o=>String(o.parent_id)===String(id)&&o.type!=='factory').forEach(o=>{rows.push({...o,depth,count:props.users.filter(u=>ancestry(u.organization_id).has(String(o.id))).length});visit(o.id,depth+1);});};visit(root,0);return rows;}
const scopedUsers=computed(()=>scope.value==='all'?props.users:selectedOrg.value?props.users.filter(u=>ancestry(u.organization_id).has(String(selectedOrg.value.id))):selected.value?.users||[]);
const filtered=computed(()=>scopedUsers.value.filter(u=>(status.value==='all'||u.active===(status.value==='active'))&&[u.name,u.login,u.job_title,u.organization_name].join(' ').toLowerCase().includes(keyword.value.toLowerCase())));
const visibleGroups=computed(()=>groups.value.filter(g=>!keyword.value||[g.name,...g.users.map(u=>[u.name,u.login].join(' '))].join(' ').toLowerCase().includes(keyword.value.toLowerCase())));
const title=computed(()=>selectedOrg.value?.path||selectedOrg.value?.name||selected.value?.name||'组织人员概览');
const roleName=code=>props.roles.find(r=>r.code===code)?.label||code;
watch(()=>[props.context.scope_kind,props.factories.length],([kind])=>{if(kind==='factory'&&scope.value==='all'&&props.factories.length)scope.value=`factory:${props.factories[0].id}`;},{immediate:true});
</script>
<template>
<section class="user-directory"><header class="ud-heading"><div><h2>用户管理</h2><small>{{ context.scope_label }}</small></div><div class="ud-tools"><input v-model.trim="keyword" type="search" aria-label="搜索人员" placeholder="搜索姓名、账号或部门"><button class="btn btn-sm btn-secondary" :disabled="loading" @click="emit('refresh')">刷新</button><button v-if="context.can_manage_users" class="btn btn-sm btn-primary" @click="emit('create',selectedOrg?.id||selected?.organization||'')">＋ 新增用户</button></div></header>
<div class="ud-layout"><aside class="ud-tree" aria-label="按组织查看用户"><button v-if="context.scope_kind==='headquarters'" class="ud-tree-overview" :class="{active:scope==='all'}" @click="scope='all'">全部组织<span>{{ users.length }}</span></button><section v-for="group in groups" :key="group.id"><button :class="{active:scope===group.id}" @click="scope=group.id"><strong>{{ group.name }}</strong><span>{{ group.users.length }}</span></button><button v-for="node in departmentRows(group)" :key="node.id" class="ud-department" :class="{active:scope==='org:'+node.id}" :style="{paddingLeft:(20+node.depth*12)+'px'}" @click="scope='org:'+node.id">{{ node.name }}<span>{{ node.count }}</span></button></section></aside>
<main class="ud-main"><header class="ud-section-heading"><h3>{{ title }}</h3><span v-if="scope==='all'">{{ factories.length }} 个厂区 · {{ users.length }} 人</span><template v-else><span>{{ scopedUsers.length }} 人</span><select v-model="status" aria-label="用户状态"><option value="all">全部状态</option><option value="active">启用</option><option value="inactive">停用</option></select></template></header><div v-if="loading" class="ud-empty">正在加载人员…</div>
<div v-else-if="scope==='all'" class="ud-table-wrap"><table class="ud-table ud-overview"><thead><tr><th>组织</th><th>人员</th><th>启用 / 停用</th><th>人员预览</th><th></th></tr></thead><tbody><tr v-for="group in visibleGroups" :key="group.id"><td><button class="ud-name" @click="scope=group.id">{{ group.name }}</button><small>{{ group.type }}</small></td><td><strong>{{ group.users.length }}</strong> 人</td><td>{{ group.users.filter(u=>u.active).length }} / {{ group.users.filter(u=>!u.active).length }}</td><td class="ud-preview">{{ group.users.slice(0,3).map(u=>u.name).join('、') || '暂无人员' }}{{ group.users.length>3?' 等':'' }}</td><td><button class="ud-link" @click="scope=group.id">查看人员 →</button></td></tr></tbody></table></div>
<div v-else class="ud-table-wrap"><table class="ud-table"><thead><tr><th>姓名 / 账号</th><th>部门 / 岗位</th><th>角色</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="user in filtered" :key="user.id"><td><strong>{{ user.name }}<em v-if="user.is_organization_manager">负责人</em></strong><small>{{ user.login }}</small></td><td>{{ org(user.organization_id)?.name || '未分配部门' }}<small v-if="user.job_title">{{ user.job_title }}</small></td><td><div class="ud-roles"><RoleBadge v-for="code in user.role_codes" :key="code" :code="code" :label="roleName(code)" /><RoleBadge v-for="code in (user.inherited_role_codes||[]).filter(code=>!user.role_codes?.includes(code))" :key="'i'+code" :code="code" :label="roleName(code)" inherited /><small v-if="!user.effective_role_codes?.length">暂无角色</small></div></td><td><span class="ud-status" :class="{disabled:!user.active}">{{ user.active?'启用':'停用' }}</span></td><td><div v-if="user.can_manage" class="ud-row-tools"><button class="ud-link" @click="emit('edit',user)">编辑</button><details><summary aria-label="更多用户操作">···</summary><div><button @click="emit('reset',user)">重置密码</button><button @click="emit('toggle',user)">{{ user.active?'停用账号':'启用账号' }}</button></div></details></div><span v-else class="ud-readonly">只读</span></td></tr></tbody></table><div v-if="!filtered.length" class="ud-empty">当前组织下没有匹配的人员</div></div>
<p v-if="scope==='unassigned'" class="ud-note">这些账号尚未明确组织归属，请逐个核对后分配，避免误授权。</p></main></div>
</section>
</template>
<style scoped>
.user-directory{min-width:0}.ud-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:18px 20px;border-bottom:1px solid var(--border-default);flex-wrap:wrap}.ud-heading>div:first-child{display:flex;align-items:baseline;gap:12px}.ud-heading h2{font-size:17px;margin:0}.ud-heading small{color:var(--text-muted);font-size:11px}.ud-tools{display:flex;align-items:center;gap:8px;margin-left:auto;flex-wrap:wrap}.ud-tools input,.ud-tools .btn,.ud-section-heading select{height:34px;box-sizing:border-box;padding:0 11px;font:inherit;font-size:12px;border-radius:6px}.ud-tools input,.ud-section-heading select{border:1px solid var(--border-default);background:var(--bg-input);color:var(--text-primary)}.ud-tools input{width:220px}.ud-layout{display:grid;grid-template-columns:210px minmax(0,1fr)}.ud-tree{padding:12px 8px;border-right:1px solid var(--border-default);min-height:320px}.ud-tree button{display:flex;justify-content:space-between;gap:10px;width:100%;padding:11px 12px;border:0;border-radius:5px;color:var(--text-secondary);background:none;text-align:left;cursor:pointer;font:inherit;font-size:12px}.ud-tree button.active{color:var(--accent-gold);background:#d4aa4e12}.ud-tree button strong{font-weight:500}.ud-tree button span{font-size:11px;color:var(--text-muted);font-variant-numeric:tabular-nums}.ud-tree section{margin-top:6px}.ud-tree .ud-department{font-size:11px;padding-top:9px;padding-bottom:9px}.ud-main{min-width:0;padding:0 20px}.ud-section-heading{display:flex;gap:10px;align-items:center;padding:16px 0}.ud-section-heading h3{font-size:14px;font-weight:500;margin:0}.ud-section-heading>span{font-size:11px;color:var(--text-muted)}.ud-section-heading select{margin-left:auto;height:30px;font-size:11px}.ud-table-wrap{overflow:auto;padding-bottom:14px}.ud-table{border-collapse:collapse;width:100%;text-align:left;font-size:12px}.ud-table th{font-size:11px;font-weight:400;color:var(--text-muted);padding:10px;background:#ffffff02;white-space:nowrap}.ud-table td{border-top:1px solid var(--border-default);padding:14px 10px;vertical-align:middle}.ud-table td:last-child{text-align:right}.ud-table strong{font-weight:500;font-size:13px}.ud-table small{display:block;color:var(--text-muted);font-size:11px;margin-top:5px}.ud-table em{display:inline-block;color:var(--accent-gold);font-size:10px;font-style:normal;margin-left:8px}.ud-link,.ud-name{border:0;background:none;color:var(--accent-gold);font:inherit;font-size:12px;white-space:nowrap;padding:0;cursor:pointer}.ud-name{color:var(--text-primary);font-size:13px;font-weight:500}.ud-roles{display:flex;flex-wrap:wrap;gap:5px;max-width:250px}.ud-status{font-size:11px;color:#91b784}.ud-status.disabled{color:var(--text-muted)}.ud-row-tools{display:flex;align-items:center;justify-content:flex-end;gap:14px}.ud-row-tools details{position:relative}.ud-row-tools summary{cursor:pointer;list-style:none;color:var(--text-muted);font-weight:600;font-size:16px}.ud-row-tools details>div{position:absolute;right:0;top:100%;display:grid;gap:2px;padding:5px;z-index:2;min-width:100px;border:1px solid var(--border-default);border-radius:6px;background:var(--bg-surface,#25231e);box-shadow:0 8px 24px #0006}.ud-row-tools details button{border:0;background:none;color:var(--text-primary);padding:8px;text-align:left;cursor:pointer;font-size:11px;white-space:nowrap}.ud-preview,.ud-readonly{font-size:11px;color:var(--text-muted)}.ud-empty{padding:38px 15px;text-align:center;font-size:12px;color:var(--text-muted)}.ud-note{font-size:11px;color:var(--text-muted);line-height:1.8}.ud-table tbody tr:hover{background:#ffffff02}@media(max-width:850px){.ud-layout{grid-template-columns:160px minmax(0,1fr)}.ud-heading{padding:16px}.ud-main{padding:0 12px}.ud-heading>div:first-child{flex-wrap:wrap;gap:6px 12px}}@media(max-width:600px){.ud-layout{grid-template-columns:1fr}.ud-tree{min-height:0;max-height:170px;overflow:auto;border-right:0;border-bottom:1px solid var(--border-default);display:flex;gap:8px}.ud-tree section{min-width:140px;margin:0}.ud-tree-overview{max-width:100px;align-self:flex-start}.ud-tools{width:100%}.ud-tools input{flex:1;width:150px}.ud-table{min-width:580px}}
</style>
